import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";

import BookingForm from "../components/BookingForm";
import BookingList from "../components/BookingList";
import Navbar from "../components/Navbar";
import Sidebar from "../components/Sidebar";
import api from "../services/api";

const clientNavItems = [
  { key: "overview", label: "Overview", icon: "◫" },
  { key: "create", label: "New Booking", icon: "+" },
  { key: "bookings", label: "My Bookings", icon: "☰" }
];

const initialFormState = {
  blockId: "",
  resourceId: "",
  bookingDate: "",
  startTime: "",
  endTime: "",
  purpose: ""
};

const ClientDashboard = () => {
  const navigate = useNavigate();
  const [activeItem, setActiveItem] = useState("overview");
  const [blocks, setBlocks] = useState([]);
  const [resources, setResources] = useState([]);
  const [bookings, setBookings] = useState([]);
  const [formData, setFormData] = useState(initialFormState);
  const [message, setMessage] = useState("");
  const [loading, setLoading] = useState(false);

  const handleLogout = () => {
    localStorage.removeItem("token");
    navigate("/login");
  };

  const loadBlocks = async () => {
    try {
      const response = await api.get("/blocks/");
      setBlocks(response.data);
    } catch (error) {
      setMessage(error.response?.data?.detail || "Could not load blocks.");
    }
  };

  const loadBookings = async () => {
    try {
      const response = await api.get("/client/bookings");
      setBookings(response.data);
    } catch (error) {
      setMessage(error.response?.data?.detail || "Could not load bookings.");
    }
  };

  const loadResources = async (blockId) => {
    if (!blockId) {
      setResources([]);
      return;
    }

    try {
      const response = await api.get(`/blocks/${blockId}/resources`);
      setResources(response.data);
    } catch (error) {
      setMessage(error.response?.data?.detail || "Could not load resources.");
    }
  };

  useEffect(() => {
    loadBlocks();
    loadBookings();
  }, []);

  useEffect(() => {
    loadResources(formData.blockId);
  }, [formData.blockId]);

  const handleChange = (event) => {
    const { name, value } = event.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value,
      ...(name === "blockId" ? { resourceId: "" } : {})
    }));
  };

  const handleAvailabilityCheck = async () => {
    setMessage("");

    try {
      const response = await api.post("/client/availability", {
        resource_id: Number(formData.resourceId),
        booking_date: formData.bookingDate,
        start_time: formData.startTime,
        end_time: formData.endTime
      });

      setMessage(response.data.available ? "Resource is available." : "Resource is already booked.");
    } catch (error) {
      setMessage(error.response?.data?.detail || "Could not check availability.");
    }
  };

  const handleSubmit = async (event) => {
    event.preventDefault();
    setLoading(true);
    setMessage("");

    try {
      await api.post("/client/bookings", {
        resource_id: Number(formData.resourceId),
        booking_date: formData.bookingDate,
        start_time: formData.startTime,
        end_time: formData.endTime,
        purpose: formData.purpose
      });

      setMessage("Booking created successfully.");
      setFormData(initialFormState);
      setResources([]);
      setActiveItem("bookings");
      await loadBookings();
    } catch (error) {
      setMessage(error.response?.data?.detail || "Booking failed.");
    } finally {
      setLoading(false);
    }
  };

  const handleCancel = async (bookingId) => {
    const reason = window.prompt("Enter cancellation reason:");
    if (!reason) {
      return;
    }

    try {
      await api.post(`/client/bookings/${bookingId}/cancel`, { reason });
      setMessage("Booking cancelled.");
      await loadBookings();
    } catch (error) {
      setMessage(error.response?.data?.detail || "Cancellation failed.");
    }
  };

  return (
    <div className="dashboard-shell">
      <Sidebar
        role="Client"
        items={clientNavItems}
        activeItem={activeItem}
        onSelect={setActiveItem}
        onLogout={handleLogout}
      />

      <main className="dashboard-main">
        <Navbar
          title="Client Booking Dashboard"
          subtitle="Manage your requests, check room availability, and track approvals."
          userRole="Client"
        />

        {message ? <div className="alert info">{message}</div> : null}

        <section className="summary-grid">
          <div className="metric-card">
            <p>Total Bookings</p>
            <h2>{bookings.length}</h2>
          </div>
          <div className="metric-card">
            <p>Pending</p>
            <h2>{bookings.filter((booking) => booking.status === "pending").length}</h2>
          </div>
          <div className="metric-card">
            <p>Approved</p>
            <h2>{bookings.filter((booking) => booking.status === "approved").length}</h2>
          </div>
        </section>

        {(activeItem === "overview" || activeItem === "create") && (
          <BookingForm
            blocks={blocks}
            resources={resources}
            formData={formData}
            onChange={handleChange}
            onSubmit={handleSubmit}
            onAvailabilityCheck={handleAvailabilityCheck}
            loading={loading}
          />
        )}

        {(activeItem === "overview" || activeItem === "bookings") && (
          <BookingList
            title="My Bookings"
            description="Track all submitted requests and cancel bookings when needed."
            bookings={bookings}
            onCancel={handleCancel}
            showActions
          />
        )}
      </main>
    </div>
  );
};

export default ClientDashboard;
